-- V90.cu: Procurement commercial controls and supplier performance.
CREATE TABLE IF NOT EXISTS procurement_ppv_analysis (ppv_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,supplier_id TEXT NOT NULL,item_master_id TEXT NOT NULL,po_id TEXT,qty NUMERIC NOT NULL,baseline_rate NUMERIC NOT NULL,actual_rate NUMERIC NOT NULL,variance_per_unit NUMERIC NOT NULL,variance_value NUMERIC NOT NULL,variance_pct NUMERIC NOT NULL,landed_baseline NUMERIC NOT NULL DEFAULT 0,landed_actual NUMERIC NOT NULL DEFAULT 0,period_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS supplier_scorecard (pp_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,supplier_id TEXT NOT NULL,period_key TEXT NOT NULL,on_time_pct NUMERIC NOT NULL DEFAULT 0,quality_accept_pct NUMERIC NOT NULL DEFAULT 0,price_score NUMERIC NOT NULL DEFAULT 0,service_score NUMERIC NOT NULL DEFAULT 0,overall_score NUMERIC NOT NULL DEFAULT 0,rank_no INTEGER,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,supplier_id,period_key));
CREATE TABLE IF NOT EXISTS procurement_rebate_settlement (settlement_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,supplier_id TEXT NOT NULL,item_master_id TEXT,period_key TEXT NOT NULL,eligible_qty NUMERIC NOT NULL DEFAULT 0,rebate_pct NUMERIC NOT NULL DEFAULT 0,rebate_value NUMERIC NOT NULL DEFAULT 0,credit_note_ref TEXT,status TEXT NOT NULL DEFAULT 'PENDING',approved_by TEXT,approved_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS procurement_budget_control (control_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_key TEXT NOT NULL,budget_value NUMERIC NOT NULL DEFAULT 0,committed_value NUMERIC NOT NULL DEFAULT 0,actual_value NUMERIC NOT NULL DEFAULT 0,available_value NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_procurement_ppv_scope ON procurement_ppv_analysis(organization_id,entity_id,period_key,supplier_id);
CREATE INDEX IF NOT EXISTS ix_supplier_scorecard_scope ON supplier_scorecard(organization_id,entity_id,period_key,rank_no);
